def roman_to_int(s):
    if not s or any(c.lower() not in 'ivxlcdm' for c in s):
        return None

    numerals = {'M': 1000, 'CM': 900, 'D': 500, 'CD': 400, 'C': 100, 'XC': 90, 'L': 50, 'XL': 40, 'X': 10, 'IX': 9, 'V': 5, 'IV': 4, 'I': 1}

    result = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in numerals:
            result += numerals[s[i:i+2]]
            i += 2
        else:
            result += numerals[s[i]]
            i += 1

    return result
